#!/usr/bin/env bash
backup_guard_die(){ echo "backup host trust refused: $1" >&2;return 1;}
backup_private_file(){ local value=$1 mode uid;[[ -f $value && ! -L $value ]]||backup_guard_die "private file unsafe"||return 1;if stat -c '%a %u' "$value" >/dev/null 2>&1;then read -r mode uid < <(stat -c '%a %u' "$value");else read -r mode uid < <(stat -f '%Lp %u' "$value");fi;[[ $uid == "$(id -u)" && $((8#$mode&077)) -eq 0 ]]||backup_guard_die "private file owner/mode unsafe";}
backup_reject_libpq_overrides(){ local allowed_service=$1 name;[[ -z ${PGPASSWORD:-} && -z ${PGOPTIONS:-} ]]||backup_guard_die "PGPASSWORD/PGOPTIONS forbidden"||return 1;while IFS='=' read -r name _;do case "$name" in PGSERVICEFILE|PGPASSFILE|"$allowed_service") :;; PG*)backup_guard_die "libpq override $name forbidden"||return 1;;esac;done < <(env);}
backup_trusted_deployment(){ local root=$1 script_dir=$2 cli_dir=$3 directory owner mode;[[ $(id -u) -ne 0 ]]||backup_guard_die "runtime must be non-root"||return 1;for directory in "$root" "$script_dir" "$cli_dir";do [[ -d $directory && ! -L $directory ]]||backup_guard_die "deployment directory unsafe"||return 1;if stat -c '%u %a' "$directory" >/dev/null 2>&1;then read -r owner mode < <(stat -c '%u %a' "$directory");else read -r owner mode < <(stat -f '%u %Lp' "$directory");fi;[[ $owner == 0 && $((8#$mode&022)) -eq 0 ]]||backup_guard_die "deployment directory must be root-owned and non-writable"||return 1;done;}
backup_canonical_path(){ local path=$1 directory base;directory=$(CDPATH= cd -- "${path%/*}"&&pwd -P)||return 1;base=${path##*/};printf '%s/%s\n' "$directory" "$base";}
backup_root_file_mode(){ local path=$1 required=$2 owner mode;if stat -c '%u %a' "$path" >/dev/null 2>&1;then read -r owner mode < <(stat -c '%u %a' "$path");else read -r owner mode < <(stat -f '%u %Lp' "$path");fi;[[ $owner == 0 && $mode == "$required" && $((8#$mode&022)) -eq 0 ]];}
backup_trusted_ledger_cli(){ local root=$1 script_dir=$2 cli=$3 manifest="$script_dir/trusted-ledger-cli.sha256" expected name extra actual canonical_cli canonical_manifest;[[ -f $cli && ! -L $cli && -f $manifest && ! -L $manifest ]]||backup_guard_die "ledger CLI trust files unsafe"||return 1;canonical_cli=$(backup_canonical_path "$cli")||return 1;canonical_manifest=$(backup_canonical_path "$manifest")||return 1;[[ $canonical_manifest == "$script_dir/trusted-ledger-cli.sha256" && $canonical_cli == "$root/apps/server/dist/admin/deletion-ledger-cli.js" ]]||backup_guard_die "ledger CLI canonical path mismatch"||return 1;backup_root_file_mode "$canonical_cli" 555&&backup_root_file_mode "$canonical_manifest" 444||backup_guard_die "ledger CLI owner/mode unsafe"||return 1;read -r expected name extra <"$canonical_manifest";[[ -z ${extra:-} && $name == apps/server/dist/admin/deletion-ledger-cli.js && $expected =~ ^[a-f0-9]{64}$ ]]||backup_guard_die "ledger CLI manifest invalid"||return 1;if command -v sha256sum >/dev/null 2>&1;then actual=$(sha256sum "$canonical_cli"|awk '{print $1}');else actual=$(shasum -a 256 "$canonical_cli"|awk '{print $1}');fi;[[ $actual == "$expected" ]]||backup_guard_die "ledger CLI digest mismatch";}
